INSERT INTO public.tools_catalog (id, name, description, category, tool_types, source, is_live, is_premium, is_free, dedicated_route, display_order, extra_categories)
VALUES
  ('brand-identity-studio', 'Brand Identity Studio', 'Get a full brand kit: name ideas, story, voice, colours, fonts, logo directions and taglines, with optional logo and mood images.', 'Marketing & Sales', ARRAY['Branding', 'Design'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy']),
  ('90-day-marketing-plan', '90-Day Marketing Plan', 'A week-by-week 90-day marketing plan with channels, budget split, content calendar, targets and what to measure each week.', 'Marketing & Sales', ARRAY['Planning', 'Marketing'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('ad-campaign-studio', 'Ad Campaign Studio', 'Plan a paid ad campaign for Meta or Google: audiences, 10 ad copies, creative briefs, budget and a testing plan, plus ad images.', 'Marketing & Sales', ARRAY['Advertising', 'Marketing'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('website-copy-studio', 'Website Copy Studio', 'Get every page of your website written: home, about, services, product pages, FAQs and contact, with SEO titles and meta text.', 'Marketing & Sales', ARRAY['Copywriting', 'Website'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('seo-audit-and-fix-plan', 'SEO Audit and Fix Plan', 'Paste your web pages and target searches to get an SEO audit with rewritten titles, missing topics, schema and a 30-day fix list.', 'Marketing & Sales', ARRAY['SEO', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('sales-playbook-builder', 'Sales Playbook Builder', 'Talk through how you sell and get a sales playbook: process stages, scripts, objection answers, email templates and targets.', 'Marketing & Sales', ARRAY['Sales', 'Document Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('sales-call-coach', 'Sales Call Coach', 'Upload a sales call recording or transcript and get a scorecard, missed buying signals, better answers and a follow-up message.', 'Marketing & Sales', ARRAY['Sales', 'Coaching', 'Audio'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('tender-and-rfp-responder', 'Tender and RFP Responder', 'Upload a tender or RFP and get the requirement checklist, eligibility check, a compliance matrix and a draft technical response.', 'Marketing & Sales', ARRAY['Sales', 'Document Tools'], 'featured', true, false, false, NULL, 0, ARRAY['Legal & Compliance']),
  ('customer-persona-lab', 'Customer Persona Lab', 'Turn reviews, survey answers or chats into 3 to 4 detailed customer personas with needs, objections, channels and messages.', 'Marketing & Sales', ARRAY['Research', 'Marketing'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('product-launch-kit', 'Product Launch Kit', 'Everything to launch a product: positioning, launch timeline, landing page, emails, social posts, press note and day-one checklist.', 'Marketing & Sales', ARRAY['Marketing', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy']),
  ('email-sequence-builder', 'Email Sequence Builder', 'Write a full email sequence for welcome, sales, abandoned cart or win-back, with subject lines, timing and A/B test ideas.', 'Marketing & Sales', ARRAY['Email', 'Copywriting'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('review-intelligence', 'Review Intelligence', 'Paste hundreds of reviews and get themes, sentiment by topic, what to fix first, words to use in ads and reply templates.', 'Marketing & Sales', ARRAY['Analytics Tools', 'Research'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling']),
  ('festive-campaign-planner', 'Festive Campaign Planner', 'Plan a Diwali, Holi, Eid, Christmas or wedding-season campaign: offers, countdown calendar, posts, WhatsApp messages and creatives.', 'Marketing & Sales', ARRAY['Marketing', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('influencer-campaign-manager', 'Influencer Campaign Manager', 'Plan an influencer campaign: creator profiles to look for, outreach messages, brief, fair fee ranges to negotiate, contract points and tracking.', 'Marketing & Sales', ARRAY['Influencer Marketing', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('whatsapp-sales-funnel', 'WhatsApp Sales Funnel', 'Design a WhatsApp sales funnel: greeting, quick replies, catalogue flow, broadcast calendar, follow-ups and re-order nudges.', 'Marketing & Sales', ARRAY['WhatsApp', 'Sales'], 'featured', true, false, false, NULL, 0, ARRAY['Online Selling']),
  ('founder-story-video-studio', 'Founder Story Video Studio', 'Tell your founder story by voice and get a 2-minute brand film script, shot list, voice-over and social cut-downs, with scene images.', 'Marketing & Sales', ARRAY['Video', 'Storytelling'], 'featured', true, false, false, NULL, 0, ARRAY['Content Creation']),
  ('referral-programme-designer', 'Referral Programme Designer', 'Design a referral programme that pays for itself: rewards worked out from your margins, rules, messages, launch plan and tracking.', 'Marketing & Sales', ARRAY['Growth', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('account-based-outreach-studio', 'Account-Based Outreach Studio', 'Paste a target company''s website or LinkedIn text and get account research, decision makers to find and personalised outreach.', 'Marketing & Sales', ARRAY['Sales', 'Research'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('event-marketing-planner', 'Event Marketing Planner', 'Plan marketing for an event, expo or workshop: registration targets, promotion calendar, partner outreach, day-of plan and follow-up.', 'Marketing & Sales', ARRAY['Events', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('press-kit-builder', 'Press Kit Builder', 'Get a press kit journalists will use: press release, fact sheet, founder bios, story angles, pitch emails and a media list plan.', 'Marketing & Sales', ARRAY['PR', 'Document Tools'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy'])
